// Deterministic time-ordered rundown of today's events (FEAT-002). Since slice 2
// this text is both the LLM's input and the fallback reply if Ollama fails —
// the webhook never answers worse than slice 1 did.
// Relies on the Calendar node's alwaysOutputData: a zero-event day still emits one empty
// item, so this node runs and can answer pleasantly instead of the workflow going silent.
const WORD_BUDGET = 120; // the reply will be spoken aloud in Phase 4
const MAX_LISTED = 8;
const words = (s) => s.trim().split(/\s+/).length;
const cut = (s, max) => {
  const parts = String(s).trim().split(/\s+/);
  return parts.length <= max ? parts.join(' ') : parts.slice(0, max).join(' ') + '…';
};
const events = $input
  .all()
  .map((item) => item.json)
  .filter((e) => e && typeof e === 'object' && e.start && (e.start.dateTime || e.start.date));
// Sort by start ourselves — deterministic, no reliance on the API's ordering options.
const startKey = (e) => e.start.dateTime ?? `${e.start.date}T00:00`;
events.sort((a, b) => startKey(a).localeCompare(startKey(b)));
const clock = (iso) => iso.slice(11, 16); // HH:MM straight from the calendar's local-offset ISO string
const range = (e) =>
  e.start.dateTime
    ? `${clock(e.start.dateTime)}-${clock((e.end && e.end.dateTime) || e.start.dateTime)}`
    : 'all day';
const place = (e) => {
  const p = (typeof e.location === 'string' && e.location.trim()) || e.hangoutLink || '';
  return p ? ` @ ${cut(p, 6)}` : '';
};
const date = $now.toFormat('yyyy-MM-dd');
const line = (e) => `- ${range(e)}: ${cut(e.summary || '(untitled)', 12)}${place(e)}`;
const build = (listed) => {
  const lines = events.slice(0, listed).map(line);
  const extra = events.length - listed;
  if (extra > 0) lines.push(`…plus ${extra} more / …y ${extra} más`);
  const n = events.length;
  return `Today (${date}) you have ${n} event${n === 1 ? '' : 's'} / Hoy tienes ${n} evento${n === 1 ? '' : 's'}:\n${lines.join('\n')}`;
};
let reply;
if (events.length === 0) {
  reply =
    'Your calendar is clear today — nothing scheduled. Enjoy! / Hoy no tienes nada en el calendario. ¡Disfruta!';
} else {
  let listed = Math.min(events.length, MAX_LISTED);
  reply = build(listed);
  while (listed > 1 && words(reply) > WORD_BUDGET) {
    listed -= 1;
    reply = build(listed);
  }
}
return [{ json: { ok: true, reply, eventCount: events.length, date } }];

// Build the Ollama request (FEAT-002 slice 2). The user's original command
// arrives in the webhook body (the gateway's SkillRequest.text) and drives the
// reply language — the prompt states the mirroring rule explicitly (settled
// decision in the dossier), in the numbered-requirements + bilingual-clause
// shape FEAT-001 tuned live on qwen2.5:7b (apps/gateway/src/intent.ts,
// buildUnknownReplyPrompt): a plain one-line 'same language' rule was NOT
// enough — the bilingual rundown text dragged English questions into Spanish
// replies until the prompt took this shape. The deterministic rundown from the
// previous node is both the LLM's input and the fallback reply carried forward
// for the finalize node, so an Ollama failure degrades to slice 1's answer,
// never to an error.
// BUG-001 (2026-08-17): on this host the OUTPUT length is the entire time
// budget. qwen2.5:7b does not fit the GTX 1050's VRAM and runs ~35% on CPU,
// so every generated token costs ~0.27 s while the prompt is nearly free.
// Requirement 4 and num_predict below are therefore NOT style knobs: they are
// what keeps the node inside its timeout, which used to be 30 s against a
// prompt that needed 31-48 s — this workflow degraded to the raw rundown on
// every day that had events, and said so nowhere. Replayed against real
// Ollama with synthetic events: "Under 100 words" / num_predict 220 took
// 25.5 s at 3 events and 48.5 s at 6; "Under 60 words" / num_predict 140
// takes 20.0 s of generation at 3 events; cold that is 6.2 s model load +
// 5.4 s prompt eval + 20.0 s = 31.6 s, 63% of the node's new 50 s. The
// detective proposed 45 s, which the same numbers put at exactly 70% — no
// margin at all once generation drifts (measured 3.61-3.93 tok/s); every
// figure they had came from an already-loaded model. Requirement 3 is deliberately left intact — naming every event with
// its time range is a FEAT-002 acceptance criterion, so it is not traded away
// for speed. The consequence, measured and accepted: a day of ~5 events or
// more cannot be phrased by this model inside any timeout that still fits the
// gateway's 60 s budget, and falls back to the deterministic rundown — which
// names every event too, and now logs why it happened. If you loosen
// requirement 4, re-measure; raising the timeout past the gateway budget
// would cost the user the fallback itself.
const MODEL = 'qwen2.5:7b'; // the instance's pulled model (infra/README.md); prompt tuned on it
const rundown = $('Format Rundown').first().json;
let userText = '';
const hook = $('Webhook').first().json;
if (hook && hook.body && typeof hook.body.text === 'string') {
  userText = hook.body.text.trim().slice(0, 300);
}
const languageRule = userText
  ? 'Written in the SAME LANGUAGE as the user\'s message: if the user wrote in English, answer in English; si el usuario escribió en español, responde en español. The calendar lines above are bilingual — ignore their language, mirror the USER.'
  : 'Written in English.';
const question = userText || 'What is on my calendar today?';
const prompt = [
  'You are Xavi, a personal assistant.',
  'The user asked about today\'s calendar.',
  `User's message: "${question}"`,
  `Calendar for ${rundown.date} (${rundown.eventCount} event(s), already in time order; each line is bilingual English/Spanish):`,
  rundown.reply,
  'Write the answer you would speak aloud, following ALL of these requirements:',
  `1. ${languageRule}`,
  '2. One short spoken paragraph — no markdown, no bullet points, no preamble, no sign-off.',
  '3. Name EVERY event from the list above, in the same order, each with its time range and its location or link when it has one. Do not invent events or details that are not in the list.',
  '4. Under 60 words in total — one short clause per event and no commentary. If that is impossible, prioritize the earliest events and say how many more there are.',
  '5. If the calendar is empty, just say so pleasantly.',
  'Plain text only — no JSON, no markdown.',
].join('\n');
return [
  {
    json: {
      ollamaBody: {
        model: MODEL,
        prompt,
        stream: false,
        // num_predict is the hard stop behind requirement 4's 60 words: 140
        // tokens is ~1.7x the 83 measured on a 3-event day, so a normal answer
        // finishes on its own and a runaway one is cut before it burns the
        // node's timeout. Finalize Reply treats a cut answer (done_reason
        // 'length') as a failure, so the user never hears half a sentence.
        options: { temperature: 0.1, num_predict: 140 },
      },
      fallbackReply: rundown.reply,
      eventCount: rundown.eventCount,
      date: rundown.date,
    },
  },
];

// Fold Ollama's answer into the AgendaSkillResult shape, guarding the word
// budget deterministically (FEAT-002 slice 2): an HTTP error item (the
// previous node's onError: continueRegularOutput), an empty answer, a
// truncated one or one blowing past the budget all fall back to the
// deterministic rundown (≤120 words by construction) — the webhook always
// answers ok: true with a non-empty reply, the pleasant empty-day line
// included. `summarized` says which path answered, for debugging and the
// reviewer.
// BUG-001 (2026-08-17) added two things, both about not failing in silence:
// (a) done_reason 'length' means num_predict cut the answer mid-sentence. Half
//     a spoken sentence is worse than the raw rundown, so it counts as a
//     failure instead of reaching the user — this is what makes a low
//     num_predict safe.
// (b) every fallback now says WHY: in the result (summaryError) and on stdout,
//     where `docker logs xavi-assistant-n8n-1` shows it. Both Phase 2 skills
//     shipped degrading on every real run and nothing anywhere said so; the
//     only trace lived in n8n's SQLite execution store. Do not drop the log
//     line: it is the single thing that makes the next silent degradation
//     visible without that archaeology.
// PRIVACY (ADR-0004): the log carries the reason only — never the prompt, the
// answer, event titles or locations. Calendar content never leaves n8n.
const WORD_CAP = 130; // grace over the ~120 target; the fallback is ≤120 by construction
const base = $('Build Summary Prompt').first().json;
const words = (s) => s.trim().split(/\s+/).length;
const raw = $input.first().json;
let text = raw && typeof raw.response === 'string' ? raw.response.trim() : '';
if (text.startsWith('"') && text.endsWith('"') && text.length > 1) {
  text = text.slice(1, -1).trim();
}
let summaryError = '';
if (raw && raw.error) {
  const detail =
    typeof raw.error === 'object' && raw.error !== null ? raw.error.message : raw.error;
  summaryError = `ollama request failed: ${String(detail).slice(0, 200)}`;
} else if (text === '') {
  summaryError = 'ollama answered without a response field';
} else if (raw.done_reason === 'length') {
  summaryError = `ollama answer truncated at num_predict (${raw.eval_count} tokens)`;
} else if (words(text) > WORD_CAP) {
  summaryError = `ollama answer of ${words(text)} words exceeds the ${WORD_CAP}-word cap`;
}
const summarized = summaryError === '';
const reply = summarized ? text : base.fallbackReply;
if (!summarized) {
  console.log(`[agenda] fell back to the deterministic rundown — ${summaryError}`);
}
const json = { ok: true, reply, eventCount: base.eventCount, date: base.date, summarized };
if (!summarized) json.summaryError = summaryError;
return [{ json }];
